CREATE TABLE current_metadata_reports (connection_name TEXT NOT NULL, library_name TEXT NOT NULL, item_id TEXT NOT NULL, file_identity TEXT NOT NULL, report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), PRIMARY KEY (connection_name, library_name, item_id, file_identity));
